package com.securecare.config;
import com.securecare.domain.enums.UserRole;import com.securecare.domain.model.UserDocument;import com.securecare.repository.UserRepository;import org.springframework.beans.factory.annotation.Value;import org.springframework.boot.CommandLineRunner;import org.springframework.context.annotation.Bean;import org.springframework.context.annotation.Configuration;import org.springframework.security.crypto.password.PasswordEncoder;import java.time.Instant;
@Configuration public class AdminBootstrap{
 @Bean CommandLineRunner createInitialAdmin(UserRepository users,PasswordEncoder encoder,@Value("${APP_ADMIN_USERNAME:}") String username,@Value("${APP_ADMIN_PASSWORD:}") String password,@Value("${APP_ADMIN_EMAIL:}") String email){return args->{if(username.isBlank()&&password.isBlank())return;if(username.isBlank()||password.length()<12)throw new IllegalStateException("Set APP_ADMIN_USERNAME and APP_ADMIN_PASSWORD (at least 12 characters)");UserDocument configured=users.findByUsername(username).orElse(null);if(configured==null)users.save(new UserDocument(null,username,encoder.encode(password),UserRole.ADMIN,email,true,Instant.now(),null));else if(configured.role()!=UserRole.ADMIN||!configured.active()||(!email.isBlank()&&!email.equals(configured.email())))users.save(new UserDocument(configured.id(),configured.username(),configured.passwordHash(),UserRole.ADMIN,email.isBlank()?configured.email():email,true,configured.createdAt(),configured.lastLoginAt(),configured.staffId(),configured.patientId()));};}
}
